const OUTPUT_FILE = "web/src/keating/nodepod-boot-files.ts";
const INCLUDE_PATTERNS = [/\.ts$/, /\.md$/, /\.py$/, /\.sh$/, /\.txt$/];
const EXCLUDE_PATTERNS = [
  /\.test\.ts$/,
  /\.spec\.ts$/,
  /node_modules/,
